#!/usr/bin/env bash
set -euo pipefail
root="$(cd "$(dirname "$0")/.." && pwd)"
tmp="$(mktemp -d)"
trap 'kill "${server_pid:-}" 2>/dev/null || true; rm -rf "$tmp"' EXIT
cp "$root/ascension.html" "$root/ascension-model.js" "$root/ascension-worker.js" "$tmp/"
python3 - "$tmp/ascension.html" <<'PY'
import sys
p=sys.argv[1]
s=open(p,encoding='utf-8').read()
seed=r'''<script>localStorage.setItem('crush-goal-optimizer-v2',JSON.stringify({goal:'ascension',ascensionCount:17,heldIngots:0,prestigeCount:1,currentCoreLevels:[0,25,0,0,0],currentSlowdownLevel:15,normalAutoUnlocked:true,afkHours:10,rankTarget:'',discardedAscensions:28,maxLevelEver:9485,compressionLockedLevel:9485,compressionTerminalSalesPerSecond:15.75,compressionRarePercent:100,compressionGemLevel:10,totalVolumeCrushLog:null,coreOverrideEnabled:false,coreOverride:129140162,manualClickRate:4,uiClickRate:4,normalAutoUpdatesPerSecond:36.5,damageBoostActive:false,dpsCalibration:1,hpCalibration:1,ingotLevels:[0,44,0,1,0,38,17,38],strategyStyle:'normal',compareApLevel:'3758',compareSlowdownLevel:'14'}));</script>'''
s=s.replace('<script src="ascension-model.js?v=r82-runtime-20260830b"></script>',seed+'<script src="ascension-model.js?v=r82-runtime-20260830b"></script>',1)
probe=r'''<script>setTimeout(()=>{const hero=document.getElementById('hero'),panel=document.getElementById('strategyPanel'),cards=document.getElementById('strategyCards'),compare=document.getElementById('apCompare'),op=document.getElementById('operationGuide');hero.classList.add('hidden');panel.classList.remove('hidden');document.getElementById('strategyVerdict').innerHTML='<b>固定★推奨</b> — 手動差は操作リスク圏内';cards.innerHTML='<div class="strategyCard fixed practical"><div class="strategyCardHead"><b>固定★ — 安定 / 放置</b><span class="strategyBadge">実戦推奨</span></div><div class="strategyEta">45m 40s</div><div class="strategyLine">固定 <strong>[0,26,21,0,15]</strong></div><div class="strategyLine">Slowdown Lv14 / Lv3758×13 → Lv50×11</div><div class="strategyBurden"><span class="pill">監視 0回</span><span class="pill">Core切替 0回</span></div></div><div class="strategyCard manual"><div class="strategyCardHead"><b>手動★ — 理論高速</b><span class="strategyBadge">理論最速</span></div><div class="strategyEta">45m 10s</div><div class="strategyLine">走行 <strong>[0,0,22,0,16]</strong></div><div class="strategyLine">固定より理論 30s短縮 / 操作余裕込み 45m 10s〜47m 0s</div><div class="strategyBurden"><span class="pill">監視 20回</span><span class="pill">Core切替 39回</span></div></div>';compare.classList.remove('hidden');document.getElementById('apCompareResult').innerHTML='ETA <b>45m 40s</b> · 実戦基準案と同等';op.classList.remove('hidden');op.innerHTML='<b>固定★で進める場合の次の操作</b><br>Core固定 → ▲PRESTIGE → PRESTIGE';const pick=(id,sel)=>document.getElementById(id)||document.querySelector(sel),box=el=>{const r=el.getBoundingClientRect();return {top:r.top,bottom:r.bottom,left:r.left,right:r.right,width:r.width,height:r.height}},layout=pick('primaryDashboard','.layout'),stateEl=pick('stateCard','.stateCard'),purchaseEl=document.getElementById('purchaseCard'),resultEl=pick('resultCard','.resultCard'),state=box(stateEl),purchase=box(purchaseEl),result=box(resultEl),goals=document.querySelector('.goals').getBoundingClientRect(),aux=[...document.querySelectorAll('[data-auxiliary]')],cols=getComputedStyle(layout).gridTemplateColumns.split(' ').filter(Boolean).length,criticalBottom=Math.max(state.bottom,purchase.bottom,result.bottom),sameTop=Math.abs(state.top-result.top)<2,noHorizontalScroll=document.documentElement.scrollWidth<=innerWidth,primaryFits=criticalBottom<=innerHeight+1,goalsCompact=goals.height<=58,auxCollapsed=aux.length>=3&&aux.every(x=>x.tagName==='DETAILS'&&!x.open),panelVisible=!panel.classList.contains('hidden'),heroHidden=hero.classList.contains('hidden'),compareVisible=!compare.classList.contains('hidden'),operationVisible=!op.classList.contains('hidden'),strategyCount=document.querySelectorAll('#strategyCards .strategyCard').length;const out=document.createElement('pre');out.id='compact-dashboard-result';out.textContent=JSON.stringify({innerWidth,innerHeight,cols,state,purchase,result,goalsHeight:goals.height,criticalBottom,sameTop,noHorizontalScroll,primaryFits,goalsCompact,auxCollapsed,panelVisible,heroHidden,compareVisible,operationVisible,strategyCount,pass:innerWidth>=1500&&cols===2&&sameTop&&noHorizontalScroll&&primaryFits&&goalsCompact&&auxCollapsed&&panelVisible&&heroHidden&&compareVisible&&operationVisible&&strategyCount===2});document.body.appendChild(out)},120)</script>'''
s=s.replace('</body>',probe+'</body>')
open(p,'w',encoding='utf-8').write(s)
PY
port=18841
python3 -m http.server "$port" --directory "$tmp" >"$tmp/server.log" 2>&1 & server_pid=$!
sleep .2
result="$(google-chrome --headless=new --disable-gpu --no-sandbox --window-size=1648,780 --virtual-time-budget=1000 --dump-dom "http://127.0.0.1:$port/ascension.html" 2>"$tmp/chrome.log" | sed -n 's/.*<pre id="compact-dashboard-result">\(.*\)<\/pre>.*/\1/p')"
echo "$result"
grep -q '"pass":true' <<<"$result"
